SELECT COUNT(SECOND_CAL.ADMIN_ID) AS COUNT FROM(
SELECT FIRST_CAL.* FROM( SELECT @row_no := @row_no + 1 AS RNUM, CBCI_ADMIN.* FROM CBCI_ADMIN WHERE ADMIN_TYPE IN (${ADMIN_TYPE}) AND ADMIN_GRADE IN (${ADMIN_GRADE}) AND ADMIN_NAME LIKE '%${ADMIN_NAME}%' )FIRST_CAL, (SELECT @row_no := 0) SALES_ROW_NO
LIMIT ${dataCnt},${dataPerPage}
)SECOND_CAL

SELECT SUBJECT_NO, (SELECT SUBJECT_NM FROM CBCI_PRIZM_SUBJECT CPS WHERE CPS.SUBJECT_NO = CPID.SUBJECT_NO AND CPS.DIVISION = ${DIVISION}) AS SUBJECT_NM, ITEM_NO, (SELECT ITEM_NM FROM CBCI_PRIZM_ITEM CPI WHERE CPI.SUBJECT_NO = CPID.SUBJECT_NO AND CPI.ITEM_NO = CPID.ITEM_NO AND CPI.DIVISION = ${DIVISION}) AS ITEN_NM, (SELECT ITEM_DEFINITION FROM CBCI_PRIZM_ITEM CPI WHERE CPI.SUBJECT_NO = CPID.SUBJECT_NO AND CPI.ITEM_NO = CPID.ITEM_NO AND CPI.DIVISION = ${DIVISION}) AS ITEM_DEFINITION, (SELECT ITEM_WEIGHT FROM CBCI_PRIZM_ITEM CPI WHERE CPI.SUBJECT_NO = CPID.SUBJECT_NO AND CPI.ITEM_NO = CPID.ITEM_NO AND CPI.DIVISION = ${DIVISION}) AS ITEM_WEIGHT, ITEM_SCORE, IFNULL(ITEM_STANDARD1, '-') AS ITEM_STANDARD1, IFNULL(OPERATOR1, '-') AS OPERATOR1, IFNULL(ITEM_STANDARD2, '-') AS ITEM_STANDARD2, IFNULL(OPERATOR2, '-') AS OPERATOR2 FROM CBCI_PRIZM_ITEM_DETAIL CPID WHERE DIVISION = ${DIVISION}
AND SUBJECT_NO = ${SUBJECT_NO} AND ITEM_NO = ${ITEM_NO}
ORDER BY SUBJECT_NO, ITEM_NO, ITEM_SCORE

