SELECT LINKED_NO, LINKED_CODE, -- 연계인증 번호 RECOMMENDED_CODE, -- 추천기관 번호 LINKED_NM, -- 연계명 LINKED_STATUS, -- 운영상태 FIRM_NM, -- 회사명 FIRM_ID, -- 사업자번호 REP_NAME, -- 대표이사 FIRM_ZIP_CODE, -- 주소(우편번호) FIRM_ADDR, -- 상세주소 DATE_FORMAT(REGI_DATE,"%Y-%m-%d") AS REGI_DATE, -- 등록일자 DATE_FORMAT(START_DATE,"%Y-%m-%d") AS START_DATE, -- 시작일자 DATE_FORMAT(END_DATE,"%Y-%m-%d") AS END_DATE, -- 종료일자 TASK_MANAGER, -- 책임자 TASK_MANAGER_POSITION, -- 책임자 직급 TASK_MANAGER_TEL, -- 책임자 연락처 CS_MANAGER, -- 고객지원 담당자 CS_MANAGER_POSITION, -- 고객지원 담당자 직급 CS_MANAGER_TEL, -- 고객지원 담당자 전화번호 CS_TEL, -- 고객지원 전화 CS_FAX, -- 고객지원 팩스 CS_EMAIL, -- 고객지원 이메일 LINKED_CONTENTS, -- 연계 내역 INPUT_DATE
FROM CBCI_LINKED_CODE WHERE
FIRM_NM like #{FIRM_NM} AND
LINKED_NM like #{LINKED_NM} AND TASK_MANAGER like #{TASK_MANAGER} ORDER BY REGI_DATE ${ORDER_BY}
LIMIT ${LIMIT}

