INSERT INTO CBCI_BILLING_CHARGE(
	  charge_code
	, charge_name
	, charge_type
	, start_date
	, expire_date
	, sub_id
	, sales_count
	, product_count
	, amount
	, sub_period
	, sub_unit
	, charge_detail
	, regi_date
) 
VALUES (
	  #{charge_code}
	, #{charge_name}
	, #{charge_type}  
	, #{start_date}
	, #{expire_date}
	, #{sub_id}
	, #{sales_count}
	, #{product_count}
	, #{amount}
	, #{sub_period}
	, #{sub_unit}
	, #{charge_detail}
	, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')
)

