	, start_date
	, end_date
	, sub_id
	, discount_rate
	, discount_amount
	, free_period
	, free_period_unit
	, promo_detail
	, input_date
) 
VALUES (
	  #{promo_code}
	, #{promo_name}
	, #{promo_target}

	, 

			#{partner_code}


			'CBCI'



	, (SELECT IF(#{start_date} <= NOW() AND #{end_date} > NOW(), 'Y', 'N'))
	, #{start_date}
	, #{end_date}
	, #{sub_id}
	, #{discount_rate}
	, #{discount_amount}
	, #{free_period}
	, #{free_period_unit}
	, #{promo_detail}
	, NOW()
)

