UPDATE CBCI_PROMOTION_CODE cpc LEFT JOIN CBCI_CHARGE_PROMOTION_CONNECTION ccpc ON cpc.promo_code = ccpc.promo_code
SET
    cpc.promo_code = #{promo_code}
  , cpc.promo_name = #{promo_name}
  , cpc.promo_target = #{promo_target}
  , cpc.partner_code = #{partner_code}
  , cpc.status = (SELECT IF(#{start_date} <= NOW() AND #{end_date} > NOW(), 'Y', 'N'))
  , cpc.start_date = #{start_date}
  , cpc.end_date = #{end_date}
  , cpc.free_period = #{free_period}
  , cpc.free_period_unit = #{free_period_unit}
  , cpc.sub_id = #{sub_id}
  , cpc.discount_rate = #{discount_rate}
  , cpc.discount_amount = #{discount_amount}
  , cpc.promo_detail = #{promo_detail}
  , cpc.upd_date = NOW()
WHERE cpc.promo_code = #{promo_code}

